function shortestAfterErasing(s: string): number {
  const stack: string[] = [];
  for (const c of s) {
    const top = stack[stack.length - 1];
    if ((c === "B" && top === "A") || (c === "D" && top === "C")) stack.pop();
    else stack.push(c);
  }
  return stack.length;
}

